mapper.insert:
INSERT INTO member(
    MEM_ID
    , MEM_PW
    , MEM_NAME

    , MEM_ADDR


    , MEM_DETAIL_ADDR

    , MEM_TELL

    , MEM_EMAIL

    , MEM_GRADE

    , MEM_BUSINESS_NUM


    , MEM_BUSINESS_NAME

    , MEM_STATUS
) VALUES (
    #{memId}
    , #{memPw}
    , #{memName}

    , #{memAddr}


    , #{memDetailAddr}

, #{memTell}

    , #{memEmail}

    , #{memGrade}

    , #{memBusinessNum}


    , #{memBusinessName}

    , COALESCE(#{memStatus}, 'ACTIVE')
);

mapper.select:
SELECT MEM_STATUS
FROM MEMBER
WHERE MEM_ID = #{memId}

mapper.update:
UPDATE MEMBER 
SET MEM_STATUS = #{status}
WHERE MEM_ID = #{memId}
